package pyc

import (
	"encoding/hex"
	"encoding/json"
	"math"
	"math/big"
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

// load reads testdata/pyc/<name> (generated by gen/gen_pyc_vectors.py with the frozen CPython).
func load(t *testing.T, name string, v any) {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", "testdata", "pyc", name))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, v); err != nil {
		t.Fatal(err)
	}
}

func hf(t *testing.T, h string) float64 {
	u, err := strconv.ParseUint(h, 16, 64)
	if err != nil {
		t.Fatal(err)
	}
	return math.Float64frombits(u)
}

// sameFloat is bit equality, except that any NaN equals any NaN (payloads of NaN arithmetic results are not
// part of the contract; f32 pack/unpack compares payloads bit for bit separately).
func sameFloat(a, b float64) bool {
	return math.Float64bits(a) == math.Float64bits(b) || math.IsNaN(a) && math.IsNaN(b)
}

func i64(t *testing.T, s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		t.Fatal(err)
	}
	return n
}

func errName(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func TestIntDiv(t *testing.T) {
	var v struct{ Cases [][4]string }
	load(t, "intdiv.json", &v)
	for _, c := range v.Cases {
		a, b := i64(t, c[0]), i64(t, c[1])
		if b == 0 {
			continue
		}
		if q, m := FloorDiv(a, b), Mod(a, b); strconv.FormatInt(q, 10) != c[2] || strconv.FormatInt(m, 10) != c[3] {
			t.Errorf("%d // %d: got %d %% %d, want %s %s", a, b, q, m, c[2], c[3])
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestFloatDiv(t *testing.T) {
	var v struct{ Cases [][4]string }
	load(t, "floatdiv.json", &v)
	for _, c := range v.Cases {
		x, y := hf(t, c[0]), hf(t, c[1])
		q, m, err := FloatDivMod(x, y)
		if err != nil {
			if c[2] != err.Error() || c[3] != err.Error() {
				t.Errorf("%v // %v: %v, want %s", x, y, err, c[2])
			}
			continue
		}
		if !sameFloat(q, hf(t, c[2])) || !sameFloat(m, hf(t, c[3])) {
			t.Errorf("%v divmod %v: got %v %v, want %v %v", x, y, q, m, hf(t, c[2]), hf(t, c[3]))
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestDTBin(t *testing.T) {
	const dt = 10_000_000.0 / 30
	var v struct{ Cases [][4]string }
	load(t, "dtbin.json", &v)
	for _, c := range v.Cases {
		ts, t0 := i64(t, c[0]), i64(t, c[1])
		q, err := FloatFloorDiv(float64(ts-t0), dt) // Python: int - int first, then int // float
		if err != nil {
			t.Fatal(err)
		}
		b := int64(q)
		nt := float64(t0) + float64(float64(b)*dt) - 1 // t0 + b * DT_TICKS - 1, left to right, no fusion
		if strconv.FormatInt(b, 10) != c[2] || !sameFloat(nt, hf(t, c[3])) {
			t.Errorf("t=%d t0=%d: got %d %v want %s %v", ts, t0, b, nt, c[2], hf(t, c[3]))
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestRound(t *testing.T) {
	var v struct {
		Round0  [][2]string
		Ndigits [][3]any
		Int     [][3]any
	}
	load(t, "round.json", &v)
	for _, c := range v.Round0 {
		x := hf(t, c[0])
		z, err := RoundInt(x)
		got := errName(err)
		if err == nil {
			got = z.String()
		}
		if got != c[1] {
			t.Errorf("round(%v) = %s, want %s", x, got, c[1])
		}
	}
	for _, c := range v.Ndigits {
		x, n := hf(t, c[0].(string)), int(c[1].(float64))
		f, err := RoundFloat(x, n)
		want := c[2].(string)
		if err != nil {
			if err.Error() != want {
				t.Errorf("round(%v, %d): %v, want %s", x, n, err, want)
			}
			continue
		}
		if len(want) != 16 || !sameFloat(f, hf(t, want)) {
			t.Errorf("round(%v, %d) = %v, want %s", x, n, f, want)
		}
	}
	for _, c := range v.Int {
		z, _ := new(big.Int).SetString(c[0].(string), 10)
		if got := RoundIntN(z, int(c[1].(float64))).String(); got != c[2].(string) {
			t.Errorf("round(%s, %v) = %s, want %s", c[0], c[1], got, c[2])
		}
	}
	t.Logf("%d + %d + %d cases", len(v.Round0), len(v.Ndigits), len(v.Int))
}

func TestF32(t *testing.T) {
	var v struct {
		Pack   [][2]string
		Unpack [][2]string
	}
	load(t, "f32.json", &v)
	for _, c := range v.Pack {
		x := hf(t, c[0])
		u, err := PackF32(x)
		got := errName(err)
		if err == nil {
			got = strconv.FormatUint(uint64(u)|1<<32, 16)[1:]
		}
		if got != c[1] {
			t.Errorf("pack(%s) = %s, want %s", c[0], got, c[1])
		}
	}
	for _, c := range v.Unpack {
		u, _ := strconv.ParseUint(c[0], 16, 32)
		if got := math.Float64bits(UnpackF32(uint32(u))); got != hfBits(t, c[1]) {
			t.Errorf("unpack(%s) = %016x, want %s", c[0], got, c[1])
		}
	}
	t.Logf("%d + %d cases", len(v.Pack), len(v.Unpack))
}

func hfBits(t *testing.T, h string) uint64 { return math.Float64bits(hf(t, h)) }

func TestRepr(t *testing.T) {
	var v struct{ Cases [][2]string }
	load(t, "repr.json", &v)
	for _, c := range v.Cases {
		if got := Repr(hf(t, c[0])); got != c[1] {
			t.Errorf("repr(%s) = %s, want %s", c[0], got, c[1])
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestJSONDumps(t *testing.T) {
	var v struct {
		Configs []struct {
			EnsureASCII bool      `json:"ensure_ascii"`
			Indent      *int      `json:"indent"`
			SortKeys    bool      `json:"sort_keys"`
			Separators  *[]string `json:"separators"`
		}
		Cases []struct {
			In   string
			Outs []string
		}
	}
	b, err := os.ReadFile(filepath.Join("..", "..", "testdata", "pyc", "json_dumps.json"))
	if err != nil {
		t.Fatal(err)
	}
	var raw struct {
		Configs json.RawMessage
		Cases   [][]json.RawMessage
	}
	if err := json.Unmarshal(b, &raw); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(raw.Configs, &v.Configs); err != nil {
		t.Fatal(err)
	}
	opts := make([]DumpOptions, len(v.Configs))
	for i, c := range v.Configs {
		opts[i] = DumpOptions{EnsureASCII: c.EnsureASCII, SortKeys: c.SortKeys}
		if c.Indent != nil {
			opts[i].Indent = *c.Indent
		}
		if c.Separators != nil {
			opts[i].ItemSep, opts[i].KeySep = (*c.Separators)[0], (*c.Separators)[1]
		}
	}
	for _, rc := range raw.Cases {
		var in string
		var outs []string
		if json.Unmarshal(rc[0], &in) != nil || json.Unmarshal(rc[1], &outs) != nil {
			t.Fatal("bad case")
		}
		obj, err := Loads([]byte(in))
		if err != nil {
			t.Fatalf("loads(%q): %v", in, err)
		}
		for i, o := range opts {
			got, err := Dumps(obj, o)
			if err != nil || got != outs[i] {
				t.Errorf("dumps(%s, %+v) = %q %v, want %q", in, o, got, err, outs[i])
			}
		}
	}
	t.Logf("%d cases x %d configs", len(raw.Cases), len(opts))
}

func TestJSONLoads(t *testing.T) {
	var v struct{ Cases [][2]*string }
	load(t, "json_loads.json", &v)
	for _, c := range v.Cases {
		obj, err := Loads([]byte(*c[0]))
		if c[1] == nil {
			if err == nil {
				t.Errorf("loads(%q) succeeded, Python raises", *c[0])
			}
			continue
		}
		if err != nil {
			t.Errorf("loads(%q): %v", *c[0], err)
			continue
		}
		if got, _ := Dumps(obj, DumpOptions{EnsureASCII: true}); got != *c[1] {
			t.Errorf("loads(%q) -> %s, want %s", *c[0], got, *c[1])
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestObjectOrder(t *testing.T) {
	o := NewObject()
	o.Set("a", 1)
	o.Set("b", 2)
	o.Set("a", 3) // reassign keeps position
	o.Set("c", 4)
	o.Delete("b")
	o.Set("b", 5) // del + insert moves to the end
	if got, _ := Dumps(o, DumpOptions{}); got != `{"a": 3, "c": 4, "b": 5}` {
		t.Fatal(got)
	}
}

func TestUTF8Replace(t *testing.T) {
	var v struct{ Cases [][2]string }
	load(t, "utf8.json", &v)
	for _, c := range v.Cases {
		in, _ := hex.DecodeString(c[0])
		if got := hex.EncodeToString([]byte(DecodeUTF8Replace(in))); got != c[1] {
			t.Errorf("decode(%s) = %s, want %s", c[0], got, c[1])
		}
	}
	t.Logf("%d cases", len(v.Cases))
}

func TestNFKDASCII(t *testing.T) {
	var v struct {
		UnidataVersion string `json:"unidata_version"`
		Cases          [][2]string
	}
	load(t, "nfkd.json", &v)
	if v.UnidataVersion != nfkdUnidataVersion {
		t.Fatalf("vectors unidata %s, table %s", v.UnidataVersion, nfkdUnidataVersion)
	}
	for _, c := range v.Cases {
		if got := NFKDASCII(c[0]); got != c[1] {
			t.Errorf("NFKDASCII(%q) = %q, want %q", c[0], got, c[1])
		}
	}
	t.Logf("%d cases", len(v.Cases))
}
